function clipPath(k){const s=1/(1+k),pts=[];
  for(let i=0;i<96;i++){const a=i/96*6.2831853,cx=Math.cos(a),cy=Math.sin(a);let lo=0,hi=1.6;
    for(let j=0;j<22;j++){const t=(lo+hi)/2,u=t*cx,v=t*cy,f=(1+k*(u*u+v*v))*s;if(Math.abs(u*f)<=1&&Math.abs(v*f)<=1)lo=t;else hi=t}
    pts.push(((lo*cx+1)*50).toFixed(2)+"% "+((lo*cy+1)*50).toFixed(2)+"%")}
  return "polygon("+pts.join(",")+")"}
