const AZ=[];
for(let i=0;i<4;i++){AZ.push([i/4,(i+1)/4,0,.18,(i+.5)/4,0]);AZ.push([i/4,(i+1)/4,.82,1,(i+.5)/4,1])}
for(let i=0;i<2;i++){AZ.push([0,.14,.18+i*.32,.5+i*.32,0,.3+i*.4]);AZ.push([.86,1,.18+i*.32,.5+i*.32,1,.3+i*.4])}
const AC=AZ.map(()=>[6,6,8]);
function ambi(){
  const w=SW(),h=SH(),sr=screen.getBoundingClientRect(),cr=cv.getBoundingClientRect();
  if(!cr.width||px.length<w*h) return;
  const hb=hasBg(),R=Math.round(hb?cr.width*1.15:Math.max(cr.width*.5,(sr.width-cr.width)*.8,(sr.height-cr.height)*1.2)),parts=[],S={L:[0,0,0,0],R:[0,0,0,0],T:[0,0,0,0],B:[0,0,0,0]};
  AZ.forEach((z,zi)=>{let r=0,g=0,b=0,n=0;const x0=z[0]*w|0,x1=z[1]*w|0,y0=z[2]*h|0,y1=z[3]*h|0,sx=Math.max(1,(x1-x0)>>3),sy=Math.max(1,(y1-y0)>>2);
    for(let y=y0;y<y1;y+=sy)for(let x=x0;x<x1;x+=sx){const c=px[y*w+x];r+=c&255;g+=(c>>8)&255;b+=(c>>16)&255;n++}
    const c=AC[zi];if(n){c[0]+=(r/n-c[0])*.3;c[1]+=(g/n-c[1])*.3;c[2]+=(b/n-c[2])*.3}
    const X=Math.round(cr.left-sr.left+z[4]*cr.width),Y=Math.round(cr.top-sr.top+z[5]*cr.height),col=(c[0]|0)+","+(c[1]|0)+","+(c[2]|0);
    const k=z[4]===0?"L":z[4]===1?"R":z[5]===0?"T":"B",a=S[k];a[0]+=c[0];a[1]+=c[1];a[2]+=c[2];a[3]++;
    parts.push("radial-gradient(circle "+R+"px at "+X+"px "+Y+"px,rgba("+col+","+(hb?.6:.72)+"),rgba("+col+",0) 72%)")});
  ambL.style.background=parts.join(",");ambL.style.mixBlendMode=hb?"screen":"normal";screen.style.background=hb?"":"#020203";
  for(const k in S){const a=S[k],n=a[3]||1;screen.style.setProperty("--a"+k,"rgb("+(a[0]/n|0)+","+(a[1]/n|0)+","+(a[2]/n|0)+")")}
}
