function readFile(file,cb){const r=new FileReader();r.onload=()=>cb(r.result);r.onerror=()=>say("No se ha podido leer el archivo.");return r}
$("rom").addEventListener("change",e=>{
  const f=e.target.files[0];if(!f) return;
  readFile(f,buf=>openFile(buf,f.name)).readAsArrayBuffer(f);e.target.value="";
});
["dragenter","dragover"].forEach(ev=>screen.addEventListener(ev,e=>{e.preventDefault();screen.classList.add("drag")}));
["dragleave","drop"].forEach(ev=>screen.addEventListener(ev,e=>{e.preventDefault();screen.classList.remove("drag")}));
screen.addEventListener("drop",e=>{
  const f=e.dataTransfer&&e.dataTransfer.files[0];if(!f) return;
  readFile(f,buf=>openFile(buf,f.name)).readAsArrayBuffer(f);
});


/* ---------- Bucle ---------- */
let last=0,acc=0,fpsN=0,fpsT=0;
function tick(t){
  if(!running) return;
  requestAnimationFrame(tick);
  let dt=t-last;last=t;if(dt>100)dt=100;
  pollPad();
  if(paused||!loaded) return;
  acc+=dt;let n=0;
  try{while(acc>=FRAME_MS&&n<4){M._retro_run();acc-=FRAME_MS;n++}}
  catch(e){setPaused(true);say("El juego se ha detenido por un error de emulación: "+(e&&e.message||e)+" Vuelve a cargar la ROM para reiniciarlo.");return}
  if(acc>FRAME_MS*4)acc=0;
  if(dirty){present();dirty=false}
  fpsN+=n;
  if(t-fpsT>=1000){status(romMeta.name+" · "+fpsN+" fps");fpsN=0;fpsT=t;if(++sramTimer>=3){sramTimer=0;sramSave()}}
}
function setPaused(p){
  paused=p;$("bPause").textContent=p?"Continuar":"Pausa";
  if(romMeta) status(romMeta.name+(p?" · en pausa":""));
  if(p) sramSave(); else{last=performance.now();acc=0}
}
$("bPause").onclick=()=>setPaused(!paused);
$("bReset").onclick=()=>{if(!loaded) return;try{M._retro_reset();say("");setPaused(false)}catch(e){say("No se ha podido reiniciar: "+e.message)}};
document.addEventListener("visibilitychange",()=>{if(document.hidden&&loaded&&!paused)setPaused(true)});

/* ---------- Entrada ---------- */
// Índices del núcleo: 0 B, 1 Y, 2 Select, 3 Start, 4-7 cruceta, 8 A, 9 X, 10 L, 11 R
const NAMES=["B","Y","Select","Start","Arriba","Abajo","Izquierda","Derecha","A","X","L","R"];
const ORDER=[4,5,6,7,0,8,1,9,10,11,2,3];
const DEF=["KeyZ","KeyA","ShiftRight","Enter","ArrowUp","ArrowDown","ArrowLeft","ArrowRight","KeyX","KeyS","KeyQ","KeyW"];
let keymap=DEF.slice();
try{const s=JSON.parse(localStorage.getItem("snes-keys"));if(Array.isArray(s)&&s.length===12)keymap=s}catch(e){}
const kb=new Array(12).fill(false),tc=new Array(12).fill(false),gp=new Array(12).fill(false);
function sync(){for(let b=0;b<12;b++)held[b]=kb[b]||tc[b]||gp[b]}
function keyLabel(c){
  const m={ArrowUp:"↑",ArrowDown:"↓",ArrowLeft:"←",ArrowRight:"→",Enter:"Intro",Space:"Espacio",ShiftLeft:"Mayús izq",ShiftRight:"Mayús der",ControlLeft:"Ctrl izq",ControlRight:"Ctrl der",AltLeft:"Alt",Tab:"Tab",Backspace:"Retroceso"};
  return m[c]||c.replace(/^Key|^Digit/,"").replace(/^Numpad/,"Num ");
}
let listening=-1;
function drawKeys(){
  const box=$("keys");box.textContent="";
  ORDER.forEach(b=>{
    const l=document.createElement("label"),s=document.createElement("span"),k=document.createElement("button");
    s.textContent=NAMES[b];k.id="key"+b;k.type="button";
    k.textContent=listening===b?"Pulsa…":keyLabel(keymap[b]);
    if(listening===b)k.className="listen";
    k.onclick=()=>{listening=listening===b?-1:b;drawKeys()};
    l.append(s,k);box.append(l);
  });
}
drawKeys();
function saveKeys(){try{localStorage.setItem("snes-keys",JSON.stringify(keymap))}catch(e){}}
$("bKeysReset").onclick=()=>{keymap=DEF.slice();listening=-1;saveKeys();drawKeys()};
window.addEventListener("keydown",e=>{
  if(!API.visible) return;
  if(listening>=0){
    e.preventDefault();
    if(e.code!=="Escape"){const o=keymap.indexOf(e.code);if(o>=0&&o!==listening)keymap[o]=keymap[listening];keymap[listening]=e.code;saveKeys()}
    listening=-1;drawKeys();return;
  }
  const t=e.target;if(t&&(t.tagName==="INPUT"||t.tagName==="SELECT"||t.tagName==="TEXTAREA")&&t.type!=="range"&&t.type!=="file") return;
  const b=keymap.indexOf(e.code);if(b<0||e.metaKey||e.ctrlKey||e.altKey) return;
  if(loaded)e.preventDefault();
  kb[b]=true;sync();
});
window.addEventListener("keyup",e=>{if(!API.visible) return;const b=keymap.indexOf(e.code);if(b>=0){kb[b]=false;sync()}});
window.addEventListener("blur",()=>{kb.fill(false);tc.fill(false);sync()});

$("pad").querySelectorAll("button").forEach(el=>{
  const b=+el.dataset.b;
  const set=v=>e=>{e.preventDefault();tc[b]=v;el.classList.toggle("on",v);sync();if(v&&el.setPointerCapture)try{el.setPointerCapture(e.pointerId)}catch(x){}};
  el.addEventListener("pointerdown",set(true));
  ["pointerup","pointercancel","lostpointercapture"].forEach(ev=>el.addEventListener(ev,set(false)));
  el.addEventListener("contextmenu",e=>e.preventDefault());
});

let padSeen=false;
function pollPad(){
  let pads;try{pads=navigator.getGamepads?navigator.getGamepads():[]}catch(e){return}
  let p=null;for(const g of pads){if(g&&g.connected){p=g;break}}
  if(!p){if(padSeen){gp.fill(false);sync();padSeen=false;$("padNote").textContent="Mando desconectado. El teclado sigue activo."}return}
  if(!padSeen){padSeen=true;$("padNote").textContent="Mando activo: "+p.id.replace(/\s*\(.*\)\s*$/,"")+". Los cuatro botones siguen la posición del mando de SNES (abajo B, derecha A, izquierda Y, arriba X), con L, R, Start y Select."}
  const B=i=>!!(p.buttons[i]&&p.buttons[i].pressed),ax=p.axes||[];
  gp[0]=B(0);gp[8]=B(1);gp[1]=B(2);gp[9]=B(3);gp[10]=B(4)||B(6);gp[11]=B(5)||B(7);gp[2]=B(8);gp[3]=B(9);
  gp[4]=B(12)||ax[1]<-.5;gp[5]=B(13)||ax[1]>.5;gp[6]=B(14)||ax[0]<-.5;gp[7]=B(15)||ax[0]>.5;
  sync();
}

/* ---------- Estados ---------- */
function hhmm(){return new Date().toLocaleTimeString("es-ES",{hour:"2-digit",minute:"2-digit",second:"2-digit"})}
function takeState(){
  const n=M._retro_serialize_size();if(!n) return null;
  const p=M._malloc(n);const ok=M._retro_serialize(p,n);
  const out=ok?M.HEAPU8.slice(p,p+n):null;M._free(p);return out;
}
function putState(u8){
  const p=M._malloc(u8.length);M.HEAPU8.set(u8,p);let ok=0;
  try{ok=M._retro_unserialize(p,u8.length)}catch(e){ok=0}
  M._free(p);
  if(ok){say("");setPaused(false)}else say("Ese estado no se puede cargar en este juego.");
  return !!ok;
}
$("bSave").onclick=()=>{
  if(!loaded) return;
  const s=takeState();if(!s){say("Este juego no permite guardar el estado.");return}
  quick=s;$("slot").textContent="Estado guardado a las "+hhmm()+" · "+Math.round(s.length/1024)+" KB";
  $("bLoad").disabled=false;$("bExport").disabled=!downloads;
};
$("bLoad").onclick=()=>{if(loaded&&quick)putState(quick)};
$("bExport").onclick=async()=>{
  if(!quick||!downloads) return;
  const base=romMeta.name.replace(/\.[^.]+$/,"").replace(/[^\w\- ]+/g,"").trim()||"partida";
  const data=JSON.stringify({formato:"consola-snes-estado-1",rom:romMeta.name,crc:romMeta.crc,estado:b64(quick)});
  try{await downloads.save({filename:base+" - estado SNES.json",data});$("slot").textContent="Exportado a las "+hhmm()}
  catch(e){if(e&&e.code!=="declined")say(e&&e.code==="rate_limited"?"Ya hay una descarga pendiente de confirmar.":"No se ha podido exportar el archivo desde esta vista.")}
};
$("stateFile").addEventListener("change",e=>{
  const f=e.target.files[0];e.target.value="";if(!f) return;
  if(!loaded){say("Carga primero la ROM del juego y después importa su estado.");return}
  readFile(f,txt=>{
    let o;try{o=JSON.parse(txt)}catch(x){say("El archivo no es un estado válido.");return}
    if(!o||o.formato!=="consola-snes-estado-1"||typeof o.estado!=="string"){say("El archivo no es un estado exportado desde esta consola de SNES.");return}
    if(o.crc!==romMeta.crc){say("Ese estado es de otra ROM ("+(o.rom||"desconocida")+", CRC "+o.crc+"). Carga ese juego antes de importarlo.");return}
    let u;try{u=unb64(o.estado)}catch(x){say("El archivo está dañado.");return}
    if(putState(u)){quick=u;$("slot").textContent="Estado importado de "+f.name;$("bLoad").disabled=false;$("bExport").disabled=!downloads}
  }).readAsText(f);
});

